# QuantArena evidence downloader. Standard library only for --bundle.
import base64, pathlib, runpy, sys, tempfile
FILES = {'evidence_v2.py': '', 'recompute_evidence.py': '', 'replay_evidence.py': ''}
with tempfile.TemporaryDirectory(prefix='quantarena-tools-') as folder:
    for name, content in FILES.items():
        pathlib.Path(folder, name).write_bytes(base64.b64decode(content))
    sys.path.insert(0, folder)
    runpy.run_path(str(pathlib.Path(folder, 'recompute_evidence.py')), run_name='__main__')
